	'kc62c5a98' => 'Calder Quay',
	'kc7ad97bc' => 'Harbourside Physiotherapy · Kofi Mensah',
	'kc85da513' => 'Un patient arrive avec un genou qui se bloque. L’IRM est faite à 11:40, le compte rendu en double lecture arrive à 16:50 et un plan est décidé le soir même.',
	'kc86344c6' => 'Dr. Siobhán Kerr',
	'kc8a11156' => 'À apporter : lettre d’adressage, pièce d’identité avec photo, résultats rénaux récents si un produit de contraste est prévu.',
